import React, { useState, useEffect } from 'react';
import { 
  BarChart3, 
  Calendar, 
  TrendingUp, 
  TrendingDown, 
  DollarSign, 
  Smartphone, 
  Wrench, 
  Headphones, 
  CreditCard,
  LogOut,
  Printer
} from 'lucide-react';
import { BRAND_NAME } from '../constants';
import { loadData, StorageKeys } from '../services/storage';

interface MonthlyReportDashboardProps {
  onLogout: () => void;
}

export const MonthlyReportDashboard: React.FC<MonthlyReportDashboardProps> = ({ onLogout }) => {
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM

  // Load Data
  const [financeData, setFinanceData] = useState<any[]>([]);
  const [repairData, setRepairData] = useState<any[]>([]);
  const [mobileData, setMobileData] = useState<any[]>([]);
  const [accessoryData, setAccessoryData] = useState<any[]>([]);
  const [installmentData, setInstallmentData] = useState<any[]>([]);

  useEffect(() => {
    setFinanceData(loadData(StorageKeys.TRANSACTIONS, []));
    setRepairData(loadData(StorageKeys.TICKETS, []));
    setMobileData(loadData(StorageKeys.MOBILE_STOCK, []));
    setAccessoryData(loadData(StorageKeys.ACCESSORIES_VOUCHERS, []));
    setInstallmentData(loadData(StorageKeys.INSTALLMENTS, []));
  }, []);

  // Calculations based on selectedMonth
  const calculateMetrics = () => {
    const [year, month] = selectedMonth.split('-').map(Number);

    const isSameMonth = (dateStr: string) => {
        if (!dateStr) return false;
        const d = new Date(dateStr);
        return d.getFullYear() === year && d.getMonth() + 1 === month;
    };

    // 1. Finance
    const financeIncome = financeData
        .filter(t => t.type === 'income' && isSameMonth(t.date))
        .reduce((sum, t) => sum + t.amount, 0);
    const financeExpense = financeData
        .filter(t => t.type === 'expense' && isSameMonth(t.date))
        .reduce((sum, t) => sum + t.amount, 0);

    // 2. Repairs
    const repairRevenue = repairData
        .filter(t => t.status === 'Completed' && isSameMonth(t.completedDate || t.date))
        .reduce((sum, t) => sum + (Number(t.finalCost) || 0), 0);
    const repairCount = repairData
        .filter(t => t.status === 'Completed' && isSameMonth(t.completedDate || t.date)).length;

    // 3. Mobile Sales
    const mobileRevenue = mobileData
        .filter(item => item.status === 'Sold' && isSameMonth(item.soldDate))
        .reduce((sum, item) => sum + item.sellingPrice, 0);
    const mobileCount = mobileData
        .filter(item => item.status === 'Sold' && isSameMonth(item.soldDate)).length;

    // 4. Accessories
    const accessoryRevenue = accessoryData
        .filter(v => v.status !== 'Refunded' && isSameMonth(v.date))
        .reduce((sum, v) => sum + v.totalAmount, 0);
    const accessoryCount = accessoryData
        .filter(v => v.status !== 'Refunded' && isSameMonth(v.date)).length;

    // 5. Installments (Calculated from schedule payments marked as Paid in this month)
    let installmentRevenue = 0;
    installmentData.forEach(plan => {
        if (plan.schedule) {
            plan.schedule.forEach((s: any) => {
                if (s.status === 'Paid' && isSameMonth(s.date)) {
                    installmentRevenue += s.amount;
                }
            });
        }
        // Also consider down payments made in this month if plan started this month
        if (isSameMonth(plan.startDate)) {
            installmentRevenue += (plan.downPayment || 0);
            installmentRevenue += (plan.documentFee || 0);
        }
    });

    const totalIncome = financeIncome + repairRevenue + mobileRevenue + accessoryRevenue + installmentRevenue;
    const netProfit = totalIncome - financeExpense;

    return {
        financeIncome,
        financeExpense,
        repairRevenue,
        repairCount,
        mobileRevenue,
        mobileCount,
        accessoryRevenue,
        accessoryCount,
        installmentRevenue,
        totalIncome,
        netProfit
    };
  };

  const metrics = calculateMetrics();

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans">
        <header className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between print:hidden">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-indigo-600 rounded-lg text-white">
                    <BarChart3 className="w-6 h-6" />
                </div>
                <h1 className="text-xl font-bold text-slate-800">{BRAND_NAME} - Monthly Report</h1>
            </div>
            <div className="flex items-center gap-4">
                <div className="flex items-center gap-2 bg-white border border-slate-200 rounded-lg px-3 py-1.5 shadow-sm">
                    <Calendar className="w-4 h-4 text-slate-400" />
                    <input 
                        type="month" 
                        value={selectedMonth} 
                        onChange={(e) => setSelectedMonth(e.target.value)}
                        className="text-sm font-bold text-slate-700 outline-none bg-transparent cursor-pointer"
                    />
                </div>
                <button onClick={handlePrint} className="p-2 text-slate-500 hover:text-indigo-600 hover:bg-indigo-50 rounded-full transition-colors">
                    <Printer className="w-5 h-5" />
                </button>
                <button onClick={onLogout} className="flex items-center gap-2 px-4 py-2 bg-red-50 text-red-600 rounded-lg text-sm font-bold hover:bg-red-100 transition-colors">
                    <LogOut className="w-4 h-4" /> Exit
                </button>
            </div>
        </header>

        <main className="flex-1 p-6 max-w-7xl mx-auto w-full space-y-6">
            {/* Overview Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-4 opacity-5"><TrendingUp className="w-24 h-24 text-emerald-600" /></div>
                    <p className="text-sm font-bold text-slate-500 uppercase">Total Income</p>
                    <h3 className="text-3xl font-bold text-emerald-600 mt-2">{metrics.totalIncome.toLocaleString()} <span className="text-sm text-slate-400">MMK</span></h3>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-4 opacity-5"><TrendingDown className="w-24 h-24 text-red-600" /></div>
                    <p className="text-sm font-bold text-slate-500 uppercase">Total Expenses</p>
                    <h3 className="text-3xl font-bold text-red-600 mt-2">{metrics.financeExpense.toLocaleString()} <span className="text-sm text-slate-400">MMK</span></h3>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-4 opacity-5"><DollarSign className="w-24 h-24 text-indigo-600" /></div>
                    <p className="text-sm font-bold text-slate-500 uppercase">Net Profit</p>
                    <h3 className={`text-3xl font-bold mt-2 ${metrics.netProfit >= 0 ? 'text-indigo-600' : 'text-red-500'}`}>{metrics.netProfit.toLocaleString()} <span className="text-sm text-slate-400">MMK</span></h3>
                </div>
            </div>

            {/* Detailed Breakdown */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Finance Sector */}
                <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
                    <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center gap-2">
                        <DollarSign className="w-5 h-5 text-slate-500" />
                        <h3 className="font-bold text-slate-700">General Finance</h3>
                    </div>
                    <div className="p-6 space-y-4">
                        <div className="flex justify-between items-center">
                            <span className="text-slate-600 font-medium">Other Income</span>
                            <span className="font-bold text-emerald-600">+{metrics.financeIncome.toLocaleString()}</span>
                        </div>
                        <div className="flex justify-between items-center">
                            <span className="text-slate-600 font-medium">Expenses</span>
                            <span className="font-bold text-red-600">-{metrics.financeExpense.toLocaleString()}</span>
                        </div>
                    </div>
                </div>

                {/* Mobile Sales */}
                <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
                    <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center gap-2">
                        <Smartphone className="w-5 h-5 text-slate-500" />
                        <h3 className="font-bold text-slate-700">Mobile Sales</h3>
                    </div>
                    <div className="p-6 space-y-4">
                        <div className="flex justify-between items-center">
                            <span className="text-slate-600 font-medium">Devices Sold</span>
                            <span className="font-bold text-slate-800">{metrics.mobileCount} Units</span>
                        </div>
                        <div className="flex justify-between items-center">
                            <span className="text-slate-600 font-medium">Total Revenue</span>
                            <span className="font-bold text-emerald-600">+{metrics.mobileRevenue.toLocaleString()}</span>
                        </div>
                    </div>
                </div>

                {/* Repair Service */}
                <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
                    <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center gap-2">
                        <Wrench className="w-5 h-5 text-slate-500" />
                        <h3 className="font-bold text-slate-700">Repair Services</h3>
                    </div>
                    <div className="p-6 space-y-4">
                        <div className="flex justify-between items-center">
                            <span className="text-slate-600 font-medium">Completed Repairs</span>
                            <span className="font-bold text-slate-800">{metrics.repairCount} Tickets</span>
                        </div>
                        <div className="flex justify-between items-center">
                            <span className="text-slate-600 font-medium">Service Revenue</span>
                            <span className="font-bold text-emerald-600">+{metrics.repairRevenue.toLocaleString()}</span>
                        </div>
                    </div>
                </div>

                {/* Accessories */}
                <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
                    <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center gap-2">
                        <Headphones className="w-5 h-5 text-slate-500" />
                        <h3 className="font-bold text-slate-700">Accessories</h3>
                    </div>
                    <div className="p-6 space-y-4">
                        <div className="flex justify-between items-center">
                            <span className="text-slate-600 font-medium">Vouchers Issued</span>
                            <span className="font-bold text-slate-800">{metrics.accessoryCount}</span>
                        </div>
                        <div className="flex justify-between items-center">
                            <span className="text-slate-600 font-medium">Sales Revenue</span>
                            <span className="font-bold text-emerald-600">+{metrics.accessoryRevenue.toLocaleString()}</span>
                        </div>
                    </div>
                </div>

                {/* Installments */}
                <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden md:col-span-2">
                    <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center gap-2">
                        <CreditCard className="w-5 h-5 text-slate-500" />
                        <h3 className="font-bold text-slate-700">Installment Collections</h3>
                    </div>
                    <div className="p-6 flex justify-between items-center">
                        <div className="text-sm text-slate-500">Includes Down Payments & Monthly Installments collected this month.</div>
                        <div className="text-xl font-bold text-emerald-600">+{metrics.installmentRevenue.toLocaleString()} MMK</div>
                    </div>
                </div>
            </div>

            <div className="text-center text-xs text-slate-400 pt-8 print:hidden">
                Generated at {new Date().toLocaleString()}
            </div>
        </main>
    </div>
  );
};

import React, { useState } from 'react';
