                      ref={barcodeInputRef}
                      type="text" 
                      placeholder="Scan Barcode / Serial Number to Quick Add to Cart..." 
                      className="w-full bg-transparent border-none outline-none text-indigo-900 placeholder-indigo-400 font-bold font-mono text-sm pl-8"
                      value={scanInput}
                      onChange={e => setScanInput(e.target.value)}
                      onKeyDown={handleBarcodeScan}
                    />
                    <div className="hidden md:block text-[10px] font-bold text-indigo-400 bg-white/50 px-2 py-1 rounded border border-indigo-100">
                      PRESS ENTER
                    </div>
                 </div>
               </div>

               <div className="flex-1 overflow-auto pb-20">
                  <table className="w-full text-left">
                     <thead className="bg-slate-50 sticky top-0 z-10">
                        <tr className="text-slate-500 text-xs uppercase font-bold tracking-wider">
                           <th className="p-4">Item Name</th>
                           <th className="p-4">Category</th>
                           <th className="p-4 text-right">Selling Price</th>
                           <th className="p-4 text-center">Stock</th>
                           <th className="p-4 text-right">Actions</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-slate-100">
                        {filteredInventory.map(item => (
                           <tr key={item.id} className="hover:bg-slate-50">
                              <td className="p-4">
                                 <div className="font-bold text-slate-800 text-sm">{item.name}</div>
                                 {item.serialNumber && <div className="text-[10px] text-slate-400 font-mono mt-0.5">SN: {item.serialNumber}</div>}
                              </td>
                              <td className="p-4 text-xs text-slate-500 font-bold px-2 py-1 rounded bg-slate-100 inline-block mt-2 ml-4 md:ml-0 md:mt-0 md:inline">{item.category}</td>
                              <td className="p-4 text-right font-bold text-slate-700">{item.price.toLocaleString()}</td>
                              <td className="p-4 text-center">
                                 <span className={`px-2 py-1 rounded text-xs font-bold ${item.quantity < 5 ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>
                                    {item.quantity}
                                 </span>
                              </td>
                              <td className="p-4 text-right">
                                 <div className="flex justify-end gap-2">
                                    <button onClick={() => handleAddToCart(item)} className="px-3 py-1 bg-emerald-600 text-white rounded-lg text-xs font-bold hover:bg-emerald-700 shadow-sm flex items-center gap-1">
                                       <Plus className="w-3 h-3" /> Cart
                                    </button>
                                    <button onClick={() => handleInventoryAction('edit', item)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg">
                                       <Edit className="w-4 h-4" />
                                    </button>
                                    <button onClick={() => handleInventoryAction('delete', item)} className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg">
                                       <Trash2 className="w-4 h-4" />
                                    </button>
                                 </div>
                              </td>
                           </tr>
                        ))}
                        {filteredInventory.length === 0 && (
                           <tr><td colSpan={5} className="p-8 text-center text-slate-400 italic">No items found.</td></tr>
                        )}
                     </tbody>
                  </table>
               </div>

               <button 
                  onClick={() => setIsCartOpen(true)}
                  className="absolute bottom-6 right-6 px-6 py-3 bg-slate-900 text-white rounded-full shadow-2xl flex items-center gap-3 hover:bg-slate-800 transition-all z-20 group"
               >
                  <div className="relative">
                     <ShoppingCart className="w-5 h-5" />
                     {cart.length > 0 && <span className="absolute -top-2 -right-2 w-4 h-4 bg-red-500 rounded-full text-[10px] flex items-center justify-center font-bold">{cart.length}</span>}
                  </div>
                  <span className="font-bold">View Cart</span>
                  <span className="bg-slate-700 px-2 py-0.5 rounded-full text-xs font-mono">{cartFinalTotal.toLocaleString()} K</span>
               </button>
            </div>
          );

        case 'sales-history':
           return (
             <div className="bg-white rounded-2xl shadow-sm border border-slate-100 flex flex-col h-full animate-fade-in">
               <div className="p-6 border-b border-slate-100">
                  <h3 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                     <History className="w-5 h-5 text-indigo-600" /> Sales History
                  </h3>
               </div>
               <div className="flex-1 overflow-auto">
                 <table className="w-full text-left">
                   <thead className="bg-slate-50 sticky top-0 z-10">
                      <tr className="text-slate-500 text-xs uppercase font-bold tracking-wider">
                         <th className="p-4">Voucher ID</th>
                         <th className="p-4">Date</th>
                         <th className="p-4">Items</th>
                         <th className="p-4 text-right">Total Amount</th>
                         <th className="p-4 text-center">Status</th>
                      </tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100">
                     {vouchers.map(v => (
                       <tr key={v.id} className="hover:bg-slate-50">
                          <td className="p-4 font-bold text-slate-700 text-sm">{v.id}</td>
                          <td className="p-4 text-sm text-slate-600">{new Date(v.date).toLocaleString()}</td>
                          <td className="p-4 text-sm text-slate-600 max-w-xs truncate">
                             {v.items.map(i => `${i.name} (x${i.quantity})`).join(', ')}
                          </td>
                          <td className="p-4 text-right font-bold text-indigo-600">{v.totalAmount.toLocaleString()}</td>
                          <td className="p-4 text-center"><span className="px-2 py-1 bg-emerald-100 text-emerald-600 text-xs font-bold rounded">{v.status}</span></td>
                       </tr>
                     ))}
                     {vouchers.length === 0 && (
                        <tr><td colSpan={5} className="p-8 text-center text-slate-400 italic">No sales history found.</td></tr>
                     )}
                   </tbody>
                 </table>
               </div>
             </div>
           );

        case 'backup':
           return (
              <div className="flex items-center justify-center h-full">
                 <div className="p-8 border-2 border-dashed border-slate-200 rounded-2xl text-center bg-slate-50">
                    <Save className="w-12 h-12 text-indigo-500 mx-auto mb-4" />
                    <h3 className="text-xl font-bold text-slate-800">Backup Data</h3>
                    <p className="text-slate-500 mb-6">Save all accessory data to file.</p>
                    <button onClick={handleAutoBackupAndLogout} className="px-6 py-2 bg-indigo-600 text-white rounded-lg font-bold">Download & Logout</button>
                 </div>
              </div>
           );
    }
  };

  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'inventory', label: 'Inventory & POS', icon: Headphones },
    { id: 'sales-history', label: 'Sales History', icon: History },
    { id: 'backup', label: 'Backup', icon: Save },
  ];

  return (
    <div className="flex h-screen w-full bg-slate-50 overflow-hidden font-sans">
      <aside className="w-64 bg-white border-r border-slate-200 flex flex-col z-20 shadow-xl">
        <div className="p-6 border-b border-slate-100">
          <h2 className="font-display font-bold text-xl text-slate-900">{BRAND_NAME}</h2>
          <p className="text-xs font-bold text-indigo-600 uppercase tracking-widest mt-1">Accessories</p>
        </div>
        <nav className="flex-1 p-4 space-y-2 overflow-y-auto pt-6">
          {menuItems.map((item) => (
            <button key={item.id} onClick={() => setCurrentView(item.id as any)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${currentView === item.id ? 'bg-indigo-50 text-indigo-600 font-bold' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900 font-medium'}`}>
              <item.icon className="w-5 h-5" /> <span>{item.label}</span>
            </button>
          ))}
        </nav>
        <div className="p-4 border-t border-slate-100">
          <button onClick={handleAutoBackupAndLogout} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-red-500 hover:bg-red-50 font-medium">
            <LogOut className="w-5 h-5" /> <span>Sign Out</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
         <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-8 z-10 sticky top-0">
            <h1 className="text-xl font-bold text-slate-800 capitalize">{currentView.replace('-', ' ')}</h1>
            <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-700 font-bold text-xs">AD</div>
         </header>
         <div className="flex-1 overflow-y-auto p-4">{renderContent()}</div>
      </main>

      {/* Cart Drawer */}
      {isCartOpen && (
         <div className="fixed inset-0 z-[60] flex justify-end bg-slate-900/40 backdrop-blur-sm animate-fade-in">
            <div className="w-full max-w-md bg-white h-full shadow-2xl flex flex-col animate-slide-left">
               <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-indigo-600 text-white">
                  <h3 className="font-bold text-lg flex items-center gap-2"><ShoppingCart className="w-5 h-5" /> Current Cart</h3>
                  <button onClick={() => setIsCartOpen(false)} className="p-2 hover:bg-indigo-500 rounded-full transition-colors"><X className="w-5 h-5" /></button>
               </div>
               <div className="flex-1 overflow-y-auto p-4 space-y-4">
                  {cart.map(item => (
                     <div key={item.id} className="flex justify-between items-center p-3 border border-slate-100 rounded-xl bg-slate-50">
                        <div>
                           <p className="font-bold text-slate-800 text-sm">{item.name}</p>
                           <p className="text-xs text-slate-500">{item.price.toLocaleString()} x {item.cartQuantity}</p>
                        </div>
                        <div className="flex items-center gap-3">
                           <div className="flex items-center gap-1 bg-white rounded-lg border border-slate-200">
                              <button onClick={() => updateCartQuantity(item.id, -1)} className="p-1 hover:bg-slate-100"><Minus className="w-3 h-3" /></button>
                              <span className="text-xs font-bold w-6 text-center">{item.cartQuantity}</span>
                              <button onClick={() => updateCartQuantity(item.id, 1)} className="p-1 hover:bg-slate-100"><Plus className="w-3 h-3" /></button>
                           </div>
                           <button onClick={() => removeFromCart(item.id)} className="text-red-500 hover:bg-red-50 p-1.5 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                        </div>
                     </div>
                  ))}
                  {cart.length === 0 && <div className="text-center text-slate-400 py-10 italic">Cart is empty.</div>}
               </div>
               <div className="p-6 border-t border-slate-100 bg-slate-50">
                  <div className="flex justify-between items-center mb-4">
                     <span className="text-slate-500 font-bold uppercase text-xs">Total Amount</span>
                     <span className="text-2xl font-bold text-indigo-600">{cartFinalTotal.toLocaleString()} K</span>
                  </div>
                  <button 
                     onClick={handleCheckout} 
                     disabled={cart.length === 0}
                     className="w-full py-4 bg-indigo-600 text-white font-bold rounded-xl shadow-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                  >
                     Checkout Now
                  </button>
               </div>
            </div>
         </div>
      )}

      {/* Item Modal */}
      {isItemModalOpen && (
         <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-sm animate-fade-in">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden mx-4 animate-slide-up">
               <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                  <h3 className="font-bold text-lg text-slate-800">{editingItem ? 'Edit Item' : 'Add New Item'}</h3>
                  <button onClick={() => setIsItemModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X className="w-5 h-5" /></button>
               </div>
               <form onSubmit={handleSaveItem} className="p-6 space-y-4">
                  <div>
                     <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Item Name</label>
                     <input required type="text" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm" value={itemFormData.name} onChange={e => setItemFormData({...itemFormData, name: e.target.value})} />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                     <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Category</label>
                        <select className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm" value={itemFormData.category} onChange={e => setItemFormData({...itemFormData, category: e.target.value})}>
                           {sortedCategories.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                        </select>
                     </div>
                     <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Price</label>
                        <input required type="number" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm" value={itemFormData.price} onChange={e => setItemFormData({...itemFormData, price: e.target.value})} />
                     </div>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                     <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Quantity</label>
                        <input required type="number" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm" value={itemFormData.quantity} onChange={e => setItemFormData({...itemFormData, quantity: e.target.value})} />
                     </div>
                     <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Barcode (Optional)</label>
                        <input type="text" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm font-mono" value={itemFormData.barcode} onChange={e => setItemFormData({...itemFormData, barcode: e.target.value})} />
                     </div>
                  </div>
                  <div>
                     <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Serial Number (Optional)</label>
                     <input type="text" className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm font-mono" value={itemFormData.serialNumber} onChange={e => setItemFormData({...itemFormData, serialNumber: e.target.value})} />
                  </div>
                  <button type="submit" className="w-full py-3 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 transition-all">{editingItem ? 'Update Item' : 'Add to Inventory'}</button>
               </form>
            </div>
         </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  Headphones, 
  ShoppingCart, 
  Save, 
  LogOut, 
  Search, 
  PlusCircle, 
  Edit, 
  Trash2, 
  Barcode, 
  Plus, 
  DollarSign, 
  TrendingUp,
  Printer,
  Minus,
  CheckCircle,
  X,
  History,
  Filter
} from 'lucide-react';
import { BRAND_NAME } from '../constants';
import { loadData, saveData, StorageKeys, createFullBackup } from '../services/storage';

interface AccessoriesSalesDashboardProps {
  onLogout: () => void;
}

interface AccessoryItem {
  id: string;
  name: string;
  category: string;
  price: number;
  quantity: number;
  barcode?: string;
  serialNumber?: string;
  minStockLevel?: number;
}

interface AccessoryCategory {
  id: string;
  name: string;
}

interface CartItem extends AccessoryItem {
  cartQuantity: number;
}

interface SalesVoucher {
  id: string;
  date: string; // ISO Date string
  items: { itemId: string; name: string; price: number; quantity: number }[];
  totalAmount: number;
  paymentMethod: 'Cash' | 'KPay' | 'WavePay';
  status: 'Completed' | 'Refunded';
}

const DEFAULT_CATEGORIES: AccessoryCategory[] = [
  { id: 'cat1', name: 'Case' },
  { id: 'cat2', name: 'Screen Protector' },
  { id: 'cat3', name: 'Charger' },
  { id: 'cat4', name: 'Cable' },
  { id: 'cat5', name: 'Audio' },
  { id: 'cat6', name: 'Power Bank' },
];

const DEFAULT_INVENTORY: AccessoryItem[] = [
  { id: '1', name: 'iPhone 15 Case - Clear', category: 'Case', price: 15000, quantity: 10, serialNumber: 'CASE001' },
  { id: '2', name: 'Glass Screen Protector', category: 'Screen Protector', price: 5000, quantity: 50, serialNumber: 'SP001' },
  { id: '3', name: '20W USB-C Power Adapter', category: 'Charger', price: 35000, quantity: 15, serialNumber: 'CHG001' },
  { id: '4', name: 'Lightning Cable', category: 'Cable', price: 8000, quantity: 20, serialNumber: 'CBL001' }
];

export const AccessoriesSalesDashboard: React.FC<AccessoriesSalesDashboardProps> = ({ onLogout }) => {
  const [currentView, setCurrentView] = useState<'dashboard' | 'inventory' | 'sales-history' | 'backup'>('dashboard');

  // Data State
  const [inventory, setInventory] = useState<AccessoryItem[]>(() => loadData(StorageKeys.ACCESSORIES_INVENTORY, DEFAULT_INVENTORY));
  const [categories, setCategories] = useState<AccessoryCategory[]>(() => loadData(StorageKeys.ACCESSORIES_CATEGORIES, DEFAULT_CATEGORIES));
  const [vouchers, setVouchers] = useState<SalesVoucher[]>(() => loadData(StorageKeys.ACCESSORIES_VOUCHERS, []));

  // Cart State
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);

  // UI/Filter State
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All');
  const [scanInput, setScanInput] = useState('');
  const barcodeInputRef = useRef<HTMLInputElement>(null);

  // Modal State
  const [isItemModalOpen, setIsItemModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<AccessoryItem | null>(null);
  const [itemFormData, setItemFormData] = useState({
    name: '',
    category: '',
    price: '',
    quantity: '',
    barcode: '',
    serialNumber: ''
  });

  // Persist Data
  useEffect(() => { saveData(StorageKeys.ACCESSORIES_INVENTORY, inventory); }, [inventory]);
  useEffect(() => { saveData(StorageKeys.ACCESSORIES_CATEGORIES, categories); }, [categories]);
  useEffect(() => { saveData(StorageKeys.ACCESSORIES_VOUCHERS, vouchers); }, [vouchers]);

  // Derived Data & Calculations
  const sortedCategories = [...categories].sort((a, b) => a.name.localeCompare(b.name));

  const filteredInventory = inventory.filter(item => {
    const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          (item.barcode && item.barcode.includes(searchTerm)) ||
                          (item.serialNumber && item.serialNumber.toLowerCase().includes(searchTerm));
    const matchesCategory = categoryFilter === 'All' || item.category === categoryFilter;
    return matchesSearch && matchesCategory;
  });

  const filteredStockValue = filteredInventory.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  const totalItems = inventory.reduce((sum, item) => sum + item.quantity, 0);
  const totalStockValue = inventory.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const lowStockItems = inventory.filter(item => item.quantity < 5).length;

  const today = new Date().toISOString().split('T')[0];
  const todaySales = vouchers
    .filter(v => v.date.startsWith(today) && v.status === 'Completed')
    .reduce((sum, v) => sum + v.totalAmount, 0);

  const cartFinalTotal = cart.reduce((sum, item) => sum + (item.price * item.cartQuantity), 0);

  // Handlers
  const handleOpenModal = () => {
    setEditingItem(null);
    setItemFormData({ name: '', category: sortedCategories[0]?.name || '', price: '', quantity: '', barcode: '', serialNumber: '' });
    setIsItemModalOpen(true);
  };

  const handleSaveItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingItem) {
      setInventory(prev => prev.map(item => item.id === editingItem.id ? {
        ...item,
        name: itemFormData.name,
        category: itemFormData.category,
        price: Number(itemFormData.price),
        quantity: Number(itemFormData.quantity),
        barcode: itemFormData.barcode,
        serialNumber: itemFormData.serialNumber
      } : item));
    } else {
      const newItem: AccessoryItem = {
        id: Date.now().toString(),
        name: itemFormData.name,
        category: itemFormData.category || (sortedCategories.length > 0 ? sortedCategories[0].name : 'General'),
        price: Number(itemFormData.price),
        quantity: Number(itemFormData.quantity),
        barcode: itemFormData.barcode,
        serialNumber: itemFormData.serialNumber
      };
      setInventory(prev => [...prev, newItem]);
    }
    setIsItemModalOpen(false);
  };

  const handleInventoryAction = (action: 'edit' | 'delete', item: AccessoryItem) => {
    if (action === 'delete') {
      if (confirm('Delete this item?')) {
        setInventory(prev => prev.filter(i => i.id !== item.id));
      }
    } else {
      setEditingItem(item);
      setItemFormData({
        name: item.name,
        category: item.category,
        price: String(item.price),
        quantity: String(item.quantity),
        barcode: item.barcode || '',
        serialNumber: item.serialNumber || ''
      });
      setIsItemModalOpen(true);
    }
  };

  const handleAddToCart = (item: AccessoryItem) => {
    if (item.quantity <= 0) {
      alert("Out of stock!");
      return;
    }

    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) {
        if (existing.cartQuantity >= item.quantity) {
           alert("Cannot add more than available stock.");
           return prev;
        }
        return prev.map(i => i.id === item.id ? { ...i, cartQuantity: i.cartQuantity + 1 } : i);
      }
      return [...prev, { ...item, cartQuantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(i => i.id !== id));
  };

  const updateCartQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = item.cartQuantity + delta;
        if (newQty > 0 && newQty <= item.quantity) {
          return { ...item, cartQuantity: newQty };
        }
      }
      return item;
    }));
  };

  const handleCheckout = () => {
    if (cart.length === 0) return;

    const voucher: SalesVoucher = {
      id: `V-${Date.now().toString().slice(-6)}`,
      date: new Date().toISOString(),
      items: cart.map(i => ({ itemId: i.id, name: i.name, price: i.price, quantity: i.cartQuantity })),
      totalAmount: cartFinalTotal,
      paymentMethod: 'Cash', // Simplify for now
      status: 'Completed'
    };

    // Update inventory
    const newInventory = inventory.map(item => {
      const cartItem = cart.find(c => c.id === item.id);
      if (cartItem) {
        return { ...item, quantity: item.quantity - cartItem.cartQuantity };
      }
      return item;
    });

    setInventory(newInventory);
    setVouchers(prev => [voucher, ...prev]);
    setCart([]);
    setIsCartOpen(false);
    alert('Sale Completed Successfully!');
  };

  const handleBarcodeScan = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && scanInput.trim()) {
      const item = inventory.find(i => i.barcode === scanInput.trim() || i.serialNumber === scanInput.trim());
      if (item) {
        handleAddToCart(item);
        setScanInput('');
      } else {
        alert('Item not found!');
      }
    }
  };

  const handleAutoBackupAndLogout = () => {
    createFullBackup('HHS_ACCESSORIES');
    setTimeout(onLogout, 500);
  };

  const renderContent = () => {
    switch (currentView) {
        case 'dashboard':
          return (
            <div className="space-y-6 animate-fade-in">
               <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                  <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm relative overflow-hidden group">
                     <div className="absolute right-0 top-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                        <DollarSign className="w-24 h-24 text-emerald-600" />
                     </div>
                     <p className="text-slate-500 text-sm font-medium">Today's Sales</p>
                     <h3 className="text-2xl font-bold text-emerald-600 mt-2">{todaySales.toLocaleString()} MMK</h3>
                  </div>
                  <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm relative overflow-hidden group">
                     <div className="absolute right-0 top-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                        <Package className="w-24 h-24 text-indigo-600" />
                     </div>
                     <p className="text-slate-500 text-sm font-medium">Total Stock Value</p>
                     <h3 className="text-2xl font-bold text-indigo-600 mt-2">{totalStockValue.toLocaleString()} MMK</h3>
                  </div>
                  <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm relative overflow-hidden group">
                     <div className="absolute right-0 top-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                        <Headphones className="w-24 h-24 text-cyan-600" />
                     </div>
                     <p className="text-slate-500 text-sm font-medium">Total Items</p>
                     <h3 className="text-2xl font-bold text-cyan-600 mt-2">{totalItems}</h3>
                  </div>
                  <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm relative overflow-hidden group">
                     <div className="absolute right-0 top-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                        <TrendingUp className="w-24 h-24 text-orange-600" />
                     </div>
                     <p className="text-slate-500 text-sm font-medium">Low Stock Alerts</p>
                     <h3 className="text-2xl font-bold text-orange-600 mt-2">{lowStockItems}</h3>
                  </div>
               </div>

               <div className="bg-white rounded-2xl border border-slate-100 shadow-sm flex flex-col">
                  <div className="p-6 border-b border-slate-100">
                      <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-4">
                          <h3 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                               <Package className="w-5 h-5 text-indigo-600" /> Stock Search & Overview
                          </h3>
                          <div className="flex flex-col md:flex-row gap-4 w-full md:w-auto">
                              <div className="relative flex-1 md:w-64">
                                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                                  <input 
                                      type="text" 
                                      placeholder="Search items..." 
                                      className="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:border-indigo-500"
                                      value={searchTerm}
                                      onChange={e => setSearchTerm(e.target.value)}
                                  />
                              </div>
                              <select 
                                  className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none"
                                  value={categoryFilter}
                                  onChange={e => setCategoryFilter(e.target.value)}
                              >
                                  <option value="All">All Categories</option>
                                  {sortedCategories.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                              </select>
                          </div>
                      </div>
