                      <div>
                         <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">Screen Lock {viewTicket.screenLock && viewTicket.screenLock.type !== 'None' ? `(${viewTicket.screenLock.type})` : ''}</p>
