import React, { useState, useRef, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Wrench, 
  PlusCircle, 
  Save, 
  LogOut, 
  Search, 
  Smartphone, 
  ClipboardList, 
  CheckCircle, 
  Clock, 
  XCircle, 
  Printer, 
  Edit, 
  Trash2, 
  Lock, 
  Unlock, 
  Battery, 
  Zap, 
  Wifi, 
  Settings,
  X,
  User,
  Phone,
  Calendar,
  ShieldAlert,
  Download,
  Upload
} from 'lucide-react';
import html2pdf from 'html2pdf.js';
import { BRAND_NAME, BRAND_ADDRESS, BRAND_CONTACT } from '../constants';
import { loadData, saveData, StorageKeys, createFullBackup } from '../services/storage';

interface RepairDashboardProps {
  onLogout: () => void;
}

type View = 'dashboard' | 'tickets' | 'add-ticket' | 'settings' | 'backup';
type TicketStatus = 'Pending' | 'In Progress' | 'Completed' | 'Delivered' | 'Cancelled';

interface RepairTicket {
  id: string;
  ticketNumber: string;
  customerName: string;
  phoneNumber: string;
  deviceModel: string;
  imei: string;
  errorType: string;
  estimatedCost: number;
  deposit: number;
  screenLock: {
    type: 'None' | 'Pin' | 'Password' | 'Pattern';
    value: string;
  };
  accessories: {
    charger: boolean;
    memoryCard: boolean;
    battery: boolean;
    simCard: boolean;
  };
  note: string;
  status: TicketStatus;
  date: string;
  completedDate?: string;
  technicianNote?: string;
}

const DEFAULT_ERRORS = [
  'Screen Replacement',
  'Battery Replacement',
  'Charging Port Issue',
  'Software Issue',
  'Water Damage',
  'Speaker/Mic Issue',
  'Camera Issue',
  'Housing Replacement',
  'Motherboard Issue',
  'Network/Signal Issue'
];

export const RepairDashboard: React.FC<RepairDashboardProps> = ({ onLogout }) => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- State ---
  const [tickets, setTickets] = useState<RepairTicket[]>(() => 
    loadData(StorageKeys.TICKETS, [])
  );

  const [repairErrors, setRepairErrors] = useState<string[]>(() => 
    loadData(StorageKeys.REPAIR_ERRORS, DEFAULT_ERRORS)
  );

  useEffect(() => {
    saveData(StorageKeys.TICKETS, tickets);
  }, [tickets]);

  useEffect(() => {
    saveData(StorageKeys.REPAIR_ERRORS, repairErrors);
  }, [repairErrors]);

  // Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    customerName: '',
    phoneNumber: '',
    deviceModel: '',
    imei: '',
    errorType: '',
    estimatedCost: '',
    deposit: '',
    screenLock: {
      type: 'None' as const,
      value: ''
    },
    accessories: {
      charger: false,
      memoryCard: false,
      battery: false,
      simCard: false
    },
    note: '',
    technicianNote: '',
    status: 'Pending' as TicketStatus
  });

  // Settings State
  const [newErrorType, setNewErrorType] = useState('');

  // Search
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<TicketStatus | 'All'>('All');

  // Print State
  const [printingTicket, setPrintingTicket] = useState<RepairTicket | null>(null);

  // --- Handlers ---

  const handleInputChange = (field: string, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleCheckboxChange = (field: keyof typeof formData.accessories) => {
    setFormData(prev => ({
      ...prev,
      accessories: {
        ...prev.accessories,
        [field]: !prev.accessories[field]
      }
    }));
  };

  const handlePatternClick = (num: number) => {
    const val = String(num);
    setFormData(prev => {
        // Toggle number in pattern or append? Usually patterns are sequences.
        // For simplicity in this UI, let's just append. If it exists, maybe reset?
        // Let's go with append.
        return {
            ...prev,
            screenLock: {
                ...prev.screenLock,
                value: prev.screenLock.value + val
            }
        };
    });
  };

  const handleSaveTicket = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId) {
      setTickets(prev => prev.map(t => {
        if (t.id === editingId) {
          const isCompleting = formData.status === 'Completed' && t.status !== 'Completed';
          return {
            ...t,
            customerName: formData.customerName,
            phoneNumber: formData.phoneNumber,
            deviceModel: formData.deviceModel,
            imei: formData.imei,
            errorType: formData.errorType,
            estimatedCost: Number(formData.estimatedCost),
            deposit: Number(formData.deposit),
            screenLock: formData.screenLock,
            accessories: formData.accessories,
            note: formData.note,
            technicianNote: formData.technicianNote,
            status: formData.status,
            completedDate: isCompleting ? new Date().toISOString().split('T')[0] : t.completedDate
          };
        }
        return t;
      }));
      alert('Repair Ticket Updated!');
      setEditingId(null);
    } else {
      const newTicket: RepairTicket = {
        id: Date.now().toString(),
        ticketNumber: `REP-${new Date().getFullYear()}-${String(tickets.length + 1).padStart(4, '0')}`,
        customerName: formData.customerName,
        phoneNumber: formData.phoneNumber,
        deviceModel: formData.deviceModel,
        imei: formData.imei,
        errorType: formData.errorType,
        estimatedCost: Number(formData.estimatedCost),
        deposit: Number(formData.deposit),
        screenLock: formData.screenLock,
        accessories: formData.accessories,
        note: formData.note,
        technicianNote: '',
        status: 'Pending',
        date: new Date().toISOString().split('T')[0]
      };
      setTickets(prev => [newTicket, ...prev]);
      alert('New Repair Ticket Created!');
    }

    resetForm();
    setCurrentView('tickets');
  };

  const handleEditTicket = (ticket: RepairTicket) => {
    setEditingId(ticket.id);
    setFormData({
      customerName: ticket.customerName,
      phoneNumber: ticket.phoneNumber,
      deviceModel: ticket.deviceModel,
      imei: ticket.imei,
      errorType: ticket.errorType,
      estimatedCost: String(ticket.estimatedCost),
      deposit: String(ticket.deposit),
      screenLock: ticket.screenLock,
      accessories: ticket.accessories,
      note: ticket.note,
      technicianNote: ticket.technicianNote || '',
      status: ticket.status
    });
    setCurrentView('add-ticket');
  };

  const handleDeleteTicket = (id: string) => {
    if (confirm('Are you sure you want to delete this ticket?')) {
      setTickets(prev => prev.filter(t => t.id !== id));
    }
  };

  const resetForm = () => {
    setFormData({
      customerName: '',
      phoneNumber: '',
      deviceModel: '',
      imei: '',
      errorType: '',
      estimatedCost: '',
      deposit: '',
      screenLock: { type: 'None', value: '' },
      accessories: { charger: false, memoryCard: false, battery: false, simCard: false },
      note: '',
      technicianNote: '',
      status: 'Pending'
    });
  };

  const handlePrint = (ticket: RepairTicket) => {
    setPrintingTicket(ticket);
    setTimeout(() => {
        const element = document.getElementById('print-ticket-content');
        if (element) {
            const opt = {
                margin: 0.2,
                filename: `Ticket_${ticket.ticketNumber}.pdf`,
                image: { type: 'jpeg', quality: 0.98 },
                html2canvas: { scale: 2, useCORS: true },
                jsPDF: { unit: 'in', format: 'a5', orientation: 'portrait' }
            };
            // @ts-ignore
            html2pdf().set(opt).from(element).save().then(() => setPrintingTicket(null));
        }
    }, 100);
  };

  const handleBackupNow = () => {
    createFullBackup('HHS_REPAIR');
  };

  const handleAutoBackupAndLogout = () => {
    createFullBackup('HHS_REPAIR');
    setTimeout(() => {
      onLogout();
    }, 500);
  };

  // --- Filtering ---
  const filteredTickets = tickets.filter(t => {
    const matchesSearch = t.customerName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.ticketNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          t.phoneNumber.includes(searchTerm);
    const matchesStatus = statusFilter === 'All' || t.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  // --- Views ---

  const renderContent = () => {
    switch(currentView) {
      case 'dashboard':
        return (
          <div className="space-y-6 animate-fade-in">
             <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
                   <p className="text-slate-500 text-sm font-medium">Pending Repairs</p>
                   <h3 className="text-3xl font-bold text-orange-600 mt-2">{tickets.filter(t => t.status === 'Pending').length}</h3>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
                   <p className="text-slate-500 text-sm font-medium">In Progress</p>
                   <h3 className="text-3xl font-bold text-blue-600 mt-2">{tickets.filter(t => t.status === 'In Progress').length}</h3>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
                   <p className="text-slate-500 text-sm font-medium">Ready to Deliver</p>
                   <h3 className="text-3xl font-bold text-emerald-600 mt-2">{tickets.filter(t => t.status === 'Completed').length}</h3>
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
                   <p className="text-slate-500 text-sm font-medium">Total Delivered</p>
                   <h3 className="text-3xl font-bold text-slate-600 mt-2">{tickets.filter(t => t.status === 'Delivered').length}</h3>
                </div>
             </div>

             <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                  <h3 className="font-bold text-slate-800">Recent Tickets</h3>
                  <button onClick={() => setCurrentView('tickets')} className="text-indigo-600 text-sm font-medium hover:underline">View All</button>
                </div>
                <div className="p-0">
                   <table className="w-full text-left">
                      <thead className="bg-slate-50 text-xs uppercase text-slate-500 font-bold">
                         <tr>
                            <th className="p-4">Ticket No</th>
                            <th className="p-4">Customer</th>
                            <th className="p-4">Device</th>
                            <th className="p-4">Issue</th>
                            <th className="p-4 text-center">Status</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                         {tickets.slice(0, 5).map(t => (
                            <tr key={t.id} className="hover:bg-slate-50">
                               <td className="p-4 font-mono text-xs font-bold text-indigo-600">{t.ticketNumber}</td>
                               <td className="p-4">
                                  <div className="font-bold text-slate-800 text-sm">{t.customerName}</div>
                                  <div className="text-xs text-slate-400">{t.phoneNumber}</div>
                               </td>
                               <td className="p-4 text-sm text-slate-600">{t.deviceModel}</td>
                               <td className="p-4 text-sm text-slate-600">{t.errorType}</td>
                               <td className="p-4 text-center">
                                  <span className={`px-2 py-1 rounded text-xs font-bold ${
                                     t.status === 'Pending' ? 'bg-orange-100 text-orange-600' :
                                     t.status === 'In Progress' ? 'bg-blue-100 text-blue-600' :
                                     t.status === 'Completed' ? 'bg-emerald-100 text-emerald-600' :
                                     t.status === 'Delivered' ? 'bg-slate-100 text-slate-600' :
                                     'bg-red-100 text-red-600'
                                  }`}>{t.status}</span>
                               </td>
                            </tr>
                         ))}
                      </tbody>
                   </table>
                </div>
             </div>
          </div>
        );

      case 'add-ticket':
        return (
          <div className="h-full flex flex-col animate-fade-in max-w-5xl mx-auto w-full">
            <div className="bg-white rounded-2xl shadow-sm border border-slate-100 flex-1 flex flex-col overflow-hidden">
               <div className="px-6 py-4 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
                 <div className="flex items-center gap-3">
                    <div className="p-2 bg-indigo-100 rounded-lg text-indigo-600">
                        {editingId ? <Edit className="w-5 h-5" /> : <PlusCircle className="w-5 h-5" />}
                    </div>
                    <h3 className="font-bold text-slate-800 text-lg">{editingId ? 'Edit Repair Ticket' : 'Create Repair Ticket'}</h3>
                 </div>
                 {editingId && (
                   <button 
                     onClick={() => { setEditingId(null); resetForm(); setCurrentView('tickets'); }}
                     className="text-sm text-red-500 font-bold hover:underline"
                   >
                     Cancel Edit
                   </button>
                 )}
               </div>

               <form onSubmit={handleSaveTicket} className="p-6 flex-1 overflow-y-auto">
                 <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                    {/* Customer & Device */}
                    <div className="space-y-6">
                       <div className="space-y-4">
                          <h4 className="font-bold text-indigo-600 text-sm uppercase tracking-wider border-b border-indigo-100 pb-2 flex items-center gap-2">
                             <User className="w-4 h-4" /> Customer Details
                          </h4>
                          <div className="grid grid-cols-2 gap-4">
                             <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Customer Name</label>
                                <input type="text" required className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm"
                                  value={formData.customerName} onChange={e => handleInputChange('customerName', e.target.value)} placeholder="Name" />
                             </div>
                             <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Phone Number</label>
                                <input type="text" required className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm"
                                  value={formData.phoneNumber} onChange={e => handleInputChange('phoneNumber', e.target.value)} placeholder="09..." />
                             </div>
                          </div>
                       </div>

                       <div className="space-y-4">
                          <h4 className="font-bold text-blue-600 text-sm uppercase tracking-wider border-b border-blue-100 pb-2 flex items-center gap-2">
                             <Smartphone className="w-4 h-4" /> Device Info
                          </h4>
                          <div className="grid grid-cols-2 gap-4">
                             <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Model</label>
                                <input type="text" required className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm"
                                  value={formData.deviceModel} onChange={e => handleInputChange('deviceModel', e.target.value)} placeholder="e.g. iPhone X" />
                             </div>
                             <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">IMEI (Optional)</label>
