                               <div className="flex justify-end gap-2">
                                  <button onClick={() => handlePrint(t)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg" title="Print Ticket">
                                     <Printer className="w-4 h-4" />
