                         </button>
                      </div>
                      <div className="flex flex-wrap gap-2">
                         {repairErrors.map(err => (
                            <div key={err} className="px-3 py-1.5 bg-slate-100 rounded-lg text-xs font-medium text-slate-700 flex items-center gap-2">
                               {err}
                               <button onClick={() => setRepairErrors(prev => prev.filter(e => e !== err))} className="text-slate-400 hover:text-red-500"><X className="w-3 h-3" /></button>
                            </div>
