            <div className="absolute top-40 right-60 w-96 h-96 bg-yellow-200 rounded-full mix-blend-multiply filter blur-3xl opacity-20 animate-blob animation-delay-2000"></div>
           </div>
           {renderContent()}
        </div>
      </main>

      {/* Printing Overlay */}
      {printingTicket && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-white">
           <div id="print-ticket-content" className="w-[148mm] min-h-[210mm] p-8 bg-white border border-slate-200 relative">
               <div className="text-center mb-6 border-b-2 border-slate-900 pb-4">
                   <h1 className="text-2xl font-bold text-slate-900 uppercase">{BRAND_NAME}</h1>
                   <p className="text-xs font-bold text-slate-600 uppercase mt-1">Mobile Service Center</p>
                   <div className="mt-2 text-[10px] text-slate-500 font-medium">
                      <p>{BRAND_ADDRESS}</p>
                      <p>Ph: {BRAND_CONTACT}</p>
                   </div>
               </div>

               <div className="flex justify-between items-end mb-6">
                   <div>
                       <p className="text-[10px] font-bold text-slate-400 uppercase">Ticket Number</p>
                       <p className="text-lg font-mono font-bold text-slate-900">{printingTicket.ticketNumber}</p>
                   </div>
                   <div className="text-right">
                       <p className="text-[10px] font-bold text-slate-400 uppercase">Date</p>
                       <p className="text-sm font-bold text-slate-700">{printingTicket.date}</p>
                   </div>
               </div>

               <div className="mb-6 p-4 bg-slate-50 border border-slate-100 rounded-xl">
                   <div className="grid grid-cols-2 gap-4 text-sm">
                       <div>
                           <p className="text-[10px] font-bold text-slate-400 uppercase">Customer</p>
                           <p className="font-bold text-slate-800">{printingTicket.customerName}</p>
                           <p className="text-xs text-slate-500">{printingTicket.phoneNumber}</p>
                       </div>
                       <div>
                           <p className="text-[10px] font-bold text-slate-400 uppercase">Device</p>
                           <p className="font-bold text-slate-800">{printingTicket.deviceModel}</p>
                           <p className="text-[10px] text-slate-500 font-mono">IMEI: {printingTicket.imei || '-'}</p>
                       </div>
                   </div>
               </div>

               <table className="w-full text-left text-sm mb-6 border-collapse">
                   <thead>
                       <tr className="border-b border-slate-300">
                           <th className="py-2 font-bold text-slate-700">Service Details</th>
                           <th className="py-2 font-bold text-slate-700 text-right">Amount</th>
                       </tr>
                   </thead>
                   <tbody>
                       <tr className="border-b border-slate-100">
                           <td className="py-3">
                               <p className="font-bold text-slate-800">{printingTicket.errorType}</p>
                               <p className="text-xs text-slate-500">{printingTicket.note}</p>
                           </td>
                           <td className="py-3 text-right font-medium">
                               {printingTicket.estimatedCost.toLocaleString()}
                           </td>
                       </tr>
                   </tbody>
                   <tfoot>
                       <tr>
                           <td className="py-3 font-bold text-slate-600 text-right">Estimated Total:</td>
                           <td className="py-3 font-bold text-slate-900 text-right">{printingTicket.estimatedCost.toLocaleString()} K</td>
                       </tr>
                       {printingTicket.deposit > 0 && (
                           <tr>
                               <td className="py-1 font-bold text-emerald-600 text-right">Deposit Paid:</td>
                               <td className="py-1 font-bold text-emerald-600 text-right">-{printingTicket.deposit.toLocaleString()} K</td>
                           </tr>
                       )}
                       <tr>
                           <td className="py-3 font-bold text-slate-800 text-right border-t border-slate-200">Balance Due:</td>
                           <td className="py-3 font-bold text-xl text-slate-900 text-right border-t border-slate-200">{(printingTicket.estimatedCost - printingTicket.deposit).toLocaleString()} K</td>
                       </tr>
                   </tfoot>
               </table>

               <div className="mb-6 grid grid-cols-2 gap-4 text-xs">
                    <div>
                        <p className="font-bold text-slate-500 mb-1">Accessories Received:</p>
                        <div className="flex flex-wrap gap-2">
                           {Object.entries(printingTicket.accessories).map(([key, val]) => (
                               val && <span key={key} className="px-2 py-0.5 bg-slate-100 rounded text-slate-600 capitalize">{key}</span>
                           ))}
                           {!Object.values(printingTicket.accessories).some(v => v) && <span className="text-slate-400 italic">None</span>}
                        </div>
                    </div>
                    <div>
                        <p className="font-bold text-slate-500 mb-1">Security:</p>
                        <p className="text-slate-700">Lock Type: {printingTicket.screenLock.type}</p>
                        {printingTicket.screenLock.type !== 'None' && <p className="text-slate-700">Code: {printingTicket.screenLock.value}</p>}
                    </div>
               </div>

               <div className="mt-auto pt-8 border-t border-slate-200 text-center">
                   <p className="text-[10px] text-slate-400 font-bold uppercase mb-8">Customer Signature</p>
                   <p className="text-[10px] text-slate-500">
                       Please bring this ticket when collecting your device. 
                       <br/>We are not responsible for data loss. Please backup your data.
                       <br/>Devices not collected within 30 days may be disposed of.
                   </p>
                   <p className="text-xs font-bold text-slate-800 mt-2">THANK YOU!</p>
               </div>
           </div>
        </div>
      )}
    </div>
  );
};

