  Hash,
  AlertCircle
} from 'lucide-react';
import html2pdf from 'html2pdf.js';
import { BRAND_NAME, BRAND_ADDRESS, BRAND_CONTACT } from '../constants';
import { loadData, saveData, StorageKeys, createFullBackup } from '../services/storage';

interface RepairDashboardProps {
  onLogout: () => void;
}

type View = 'dashboard' | 'active-tickets' | 'completed-tickets' | 'new-ticket' | 'backup';
type RepairStatus = 'Pending' | 'In Progress' | 'Completed' | 'Cancelled' | 'Cannot Fix';

interface RepairTicket {
  id: string;
  customerName: string;
  phoneNumber: string;
  deviceBrand: string;
  deviceModel: string;
  imei: string;
  passcode: string; // or pattern
  errorType: string;
  errorDescription: string;
  estimatedCost: number;
  finalCost?: number;
  status: RepairStatus;
  date: string; // Created Date
  completedDate?: string;
  technicianNote?: string;
}

const DEFAULT_TICKETS: RepairTicket[] = [
  {
    id: 'REP-1001',
    customerName: 'U Ba',
    phoneNumber: '09123456789',
    deviceBrand: 'Samsung',
    deviceModel: 'Galaxy A12',
    imei: '35462718273645',
    passcode: '1234',
    errorType: 'Screen Replacement',
    errorDescription: 'Cracked screen, touch not working',
    estimatedCost: 45000,
    status: 'Pending',
    date: new Date().toISOString().split('T')[0]
  }
];

export const RepairDashboard: React.FC<RepairDashboardProps> = ({ onLogout }) => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- State ---
  const [tickets, setTickets] = useState<RepairTicket[]>(() => 
    loadData(StorageKeys.TICKETS, DEFAULT_TICKETS)
  );

  useEffect(() => {
    saveData(StorageKeys.TICKETS, tickets);
  }, [tickets]);

  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'All' | RepairStatus>('All');

  // Form State
  const [formData, setFormData] = useState({
    customerName: '',
    phoneNumber: '',
    deviceBrand: '',
    deviceModel: '',
    imei: '',
    passcode: '',
    errorType: '',
    errorDescription: '',
    estimatedCost: ''
  });
  const [editingId, setEditingId] = useState<string | null>(null);

  // Modal States
  const [viewingTicket, setViewingTicket] = useState<RepairTicket | null>(null);

  // Service Action Modal (for status change / completion)
  const [isServiceModalOpen, setIsServiceModalOpen] = useState(false);
  const [serviceActionTicket, setServiceActionTicket] = useState<RepairTicket | null>(null);
  const [serviceActionCost, setServiceActionCost] = useState<number | string>('');
  const [serviceActionStatus, setServiceActionStatus] = useState<RepairStatus>('Completed');
  const [serviceNote, setServiceNote] = useState('');

  // Security Modal
  const [isSecurityModalOpen, setIsSecurityModalOpen] = useState(false);
  const [securityPassword, setSecurityPassword] = useState('');
  const [securityError, setSecurityError] = useState('');
  const [securityActionTicket, setSecurityActionTicket] = useState<RepairTicket | null>(null);

  // --- Handlers ---

  const handleInputChange = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleSaveTicket = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId) {
      setTickets(prev => prev.map(t => 
        t.id === editingId ? {
          ...t,
          customerName: formData.customerName,
          phoneNumber: formData.phoneNumber,
          deviceBrand: formData.deviceBrand,
          deviceModel: formData.deviceModel,
          imei: formData.imei,
          passcode: formData.passcode,
          errorType: formData.errorType,
          errorDescription: formData.errorDescription,
          estimatedCost: Number(formData.estimatedCost)
        } : t
      ));
      alert('Ticket updated successfully!');
      setEditingId(null);
    } else {
      const newTicket: RepairTicket = {
        id: `REP-${1000 + tickets.length + 1}`,
        customerName: formData.customerName,
        phoneNumber: formData.phoneNumber,
        deviceBrand: formData.deviceBrand,
        deviceModel: formData.deviceModel,
        imei: formData.imei,
        passcode: formData.passcode,
        errorType: formData.errorType,
        errorDescription: formData.errorDescription,
        estimatedCost: Number(formData.estimatedCost),
        status: 'Pending',
        date: new Date().toISOString().split('T')[0]
      };
      setTickets(prev => [newTicket, ...prev]);
      alert('Repair Ticket Created!');
    }

    // Reset Form
    setFormData({
       customerName: '', phoneNumber: '', deviceBrand: '', deviceModel: '', 
       imei: '', passcode: '', errorType: '', errorDescription: '', estimatedCost: ''
    });
    setCurrentView('active-tickets');
  };

  const initiateServiceAction = (t: RepairTicket) => {
    setServiceActionTicket(t);
    setServiceActionCost(t.finalCost || t.estimatedCost);
    setServiceActionStatus(t.status === 'Pending' ? 'In Progress' : 'Completed');
    setServiceNote(t.technicianNote || '');
    setIsServiceModalOpen(true);
  };

  const handleServiceSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!serviceActionTicket) return;

    setTickets(prev => prev.map(t => 
      t.id === serviceActionTicket.id ? {
        ...t,
        status: serviceActionStatus,
        finalCost: serviceActionStatus === 'Completed' ? Number(serviceActionCost) : t.finalCost,
        technicianNote: serviceNote,
        completedDate: (serviceActionStatus === 'Completed' || serviceActionStatus === 'Cannot Fix') ? new Date().toISOString().split('T')[0] : t.completedDate
      } : t
    ));

    setIsServiceModalOpen(false);
    setServiceActionTicket(null);
  };

  const initiateDelete = (t: RepairTicket) => {
    setSecurityActionTicket(t);
    setSecurityPassword('');
    setSecurityError('');
    setIsSecurityModalOpen(true);
  };

  const handleSecuritySubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (securityPassword === '1471656') {
       if (securityActionTicket) {
         setTickets(prev => prev.filter(t => t.id !== securityActionTicket.id));
         setSecurityActionTicket(null);
       }
       setIsSecurityModalOpen(false);
    } else {
       setSecurityError('Incorrect Password');
    }
  };

  const handleEdit = (t: RepairTicket) => {
    setEditingId(t.id);
    setFormData({
      customerName: t.customerName,
      phoneNumber: t.phoneNumber,
      deviceBrand: t.deviceBrand,
      deviceModel: t.deviceModel,
      imei: t.imei,
      passcode: t.passcode,
      errorType: t.errorType,
      errorDescription: t.errorDescription,
      estimatedCost: t.estimatedCost.toString()
    });
    setCurrentView('new-ticket');
  };

  const handlePrintTicket = (ticket: RepairTicket) => {
     // Trigger PDF logic or print
     const element = document.getElementById('ticket-receipt');
     if (element) {
        // @ts-ignore
        if (window.html2pdf) {
            const opt = {
               margin: 0.2,
               filename: `Repair_${ticket.id}.pdf`,
               image: { type: 'jpeg', quality: 0.98 },
               html2canvas: { scale: 2 },
               jsPDF: { unit: 'in', format: 'a5', orientation: 'portrait' }
            };
            // @ts-ignore
            window.html2pdf().set(opt).from(element).save();
        } else {
            window.print();
        }
     }
  };

  const handleBackupNow = () => {
    createFullBackup('HHS_REPAIR');
  };

  const handleAutoBackupAndLogout = () => {
    createFullBackup('HHS_REPAIR');
    setTimeout(() => {
      onLogout();
    }, 500);
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const content = event.target?.result as string;
        const data = JSON.parse(content);
        if (data.tickets && Array.isArray(data.tickets)) {
          setTickets(data.tickets);
          alert('Repair data restored successfully!');
        } else {
          alert('Invalid backup file.');
        }
      } catch (error) {
        alert('Error parsing file.');
      }
    };
    reader.readAsText(file);
  };

  // --- Filtering ---
  const getFilteredTickets = (view: 'active' | 'completed') => {
    return tickets.filter(t => {
      const matchesSearch = t.customerName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            t.id.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            t.phoneNumber.includes(searchTerm);

      const isActive = ['Pending', 'In Progress'].includes(t.status);
      const isCompleted = ['Completed', 'Cancelled', 'Cannot Fix'].includes(t.status);

      const viewMatch = view === 'active' ? isActive : isCompleted;

      if (statusFilter !== 'All' && t.status !== statusFilter) return false;

      return matchesSearch && viewMatch;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  };

  // --- Stats ---
  const pendingCount = tickets.filter(t => t.status === 'Pending').length;
  const inProgressCount = tickets.filter(t => t.status === 'In Progress').length;
  const completedToday = tickets.filter(t => t.status === 'Completed' && t.completedDate === new Date().toISOString().split('T')[0]).length;
  const todayRevenue = tickets
    .filter(t => t.status === 'Completed' && t.completedDate === new Date().toISOString().split('T')[0])
    .reduce((sum, t) => sum + (t.finalCost || 0), 0);

  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'active-tickets', label: 'Active Repairs', icon: Clock },
    { id: 'completed-tickets', label: 'Completed History', icon: CheckCircle },
    { id: 'new-ticket', label: 'New Ticket', icon: PlusCircle },
    { id: 'backup', label: 'Data Backup', icon: Save },
  ];

  const renderContent = () => {
    switch(currentView) {
      case 'dashboard':
        return (
          <div className="space-y-6 animate-fade-in">
             <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm group hover:border-indigo-200 transition-colors">
                   <div className="flex justify-between items-start mb-4">
                      <div>
                         <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Pending</p>
                         <h3 className="text-3xl font-bold text-slate-800 mt-1">{pendingCount}</h3>
                      </div>
                      <div className="p-3 bg-amber-50 rounded-xl text-amber-600"><Clock className="w-6 h-6" /></div>
                   </div>
                   <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                      <div className="bg-amber-500 h-full rounded-full" style={{ width: `${(pendingCount / (tickets.length || 1)) * 100}%` }}></div>
                   </div>
                </div>

                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm group hover:border-blue-200 transition-colors">
                   <div className="flex justify-between items-start mb-4">
                      <div>
                         <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">In Progress</p>
                         <h3 className="text-3xl font-bold text-slate-800 mt-1">{inProgressCount}</h3>
                      </div>
                      <div className="p-3 bg-blue-50 rounded-xl text-blue-600"><Wrench className="w-6 h-6" /></div>
                   </div>
                   <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                      <div className="bg-blue-500 h-full rounded-full" style={{ width: `${(inProgressCount / (tickets.length || 1)) * 100}%` }}></div>
                   </div>
                </div>

                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm group hover:border-emerald-200 transition-colors">
                   <div className="flex justify-between items-start mb-4">
                      <div>
                         <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Completed Today</p>
                         <h3 className="text-3xl font-bold text-slate-800 mt-1">{completedToday}</h3>
                      </div>
                      <div className="p-3 bg-emerald-50 rounded-xl text-emerald-600"><CheckCircle className="w-6 h-6" /></div>
                   </div>
                   <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                      <div className="bg-emerald-500 h-full rounded-full" style={{ width: '100%' }}></div>
                   </div>
                </div>

                <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm group hover:border-indigo-200 transition-colors">
                   <div className="flex justify-between items-start mb-4">
                      <div>
                         <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Revenue Today</p>
                         <h3 className="text-2xl font-bold text-slate-800 mt-1">{todayRevenue.toLocaleString()} K</h3>
                      </div>
                      <div className="p-3 bg-indigo-50 rounded-xl text-indigo-600"><DollarSign className="w-6 h-6" /></div>
                   </div>
                   <p className="text-xs text-slate-400 font-medium">Estimated Revenue based on completed tickets</p>
                </div>
             </div>

             <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                  <h3 className="font-bold text-slate-800">Recent Tickets</h3>
                  <button onClick={() => setCurrentView('active-tickets')} className="text-indigo-600 text-sm font-medium hover:underline">View All</button>
                </div>
                <div className="p-0">
                   <table className="w-full text-left">
                      <thead className="bg-slate-50 text-xs uppercase text-slate-500 font-bold">
                         <tr>
                            <th className="p-4">Ticket ID</th>
                            <th className="p-4">Customer</th>
                            <th className="p-4">Device</th>
                            <th className="p-4">Issue</th>
                            <th className="p-4 text-center">Status</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                         {tickets.slice(0, 5).map(t => (
                            <tr key={t.id} className="hover:bg-slate-50">
                               <td className="p-4 font-bold text-indigo-600 text-sm">{t.id}</td>
                               <td className="p-4 font-medium text-slate-700 text-sm">{t.customerName}</td>
                               <td className="p-4 text-sm text-slate-600">{t.deviceBrand} {t.deviceModel}</td>
                               <td className="p-4 text-sm text-slate-500">{t.errorType}</td>
                               <td className="p-4 text-center">
                                  <span className={`px-2 py-1 rounded text-xs font-bold ${
                                     t.status === 'Completed' ? 'bg-emerald-100 text-emerald-600' :
                                     t.status === 'Pending' ? 'bg-amber-100 text-amber-600' :
                                     t.status === 'In Progress' ? 'bg-blue-100 text-blue-600' : 'bg-red-100 text-red-600'
                                  }`}>{t.status}</span>
                               </td>
                            </tr>
                         ))}
                      </tbody>
                   </table>
                </div>
             </div>
          </div>
        );

      case 'new-ticket':
         return (
             <div className="max-w-4xl mx-auto animate-fade-in h-full flex flex-col">
                <div className="bg-white rounded-2xl shadow-sm border border-slate-100 flex-1 flex flex-col overflow-hidden">
                   <div className="px-6 py-4 bg-slate-50 border-b border-slate-100 flex justify-between items-center">
                      <div className="flex items-center gap-3">
                         <div className="p-2 bg-indigo-100 rounded-lg text-indigo-600">
                            {editingId ? <Edit className="w-5 h-5" /> : <PlusCircle className="w-5 h-5" />}
                         </div>
                         <h3 className="font-bold text-slate-800 text-lg">{editingId ? 'Edit Repair Ticket' : 'Create New Ticket'}</h3>
                      </div>
                      {editingId && (
                         <button onClick={() => { setEditingId(null); setCurrentView('active-tickets'); }} className="text-red-500 text-sm font-bold hover:underline">Cancel Edit</button>
                      )}
                   </div>

                   <form onSubmit={handleSaveTicket} className="flex-1 overflow-y-auto p-6 space-y-6">
                      {/* Customer Info */}
                      <div className="space-y-4">
                         <h4 className="font-bold text-indigo-600 text-sm uppercase tracking-wider border-b border-indigo-100 pb-2 flex items-center gap-2">
                             <User className="w-4 h-4" /> Customer Details
                         </h4>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Customer Name</label>
                               <input type="text" required className="w-full px-4 py-2 border rounded-lg text-sm" placeholder="Enter name" value={formData.customerName} onChange={e => handleInputChange('customerName', e.target.value)} />
                            </div>
                            <div>
                               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Phone Number</label>
                               <input type="text" required className="w-full px-4 py-2 border rounded-lg text-sm" placeholder="09..." value={formData.phoneNumber} onChange={e => handleInputChange('phoneNumber', e.target.value)} />
                            </div>
                         </div>
                      </div>

                      {/* Device Info */}
                      <div className="space-y-4">
                         <h4 className="font-bold text-blue-600 text-sm uppercase tracking-wider border-b border-blue-100 pb-2 flex items-center gap-2">
                             <Smartphone className="w-4 h-4" /> Device Info
                         </h4>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Brand</label>
                               <input type="text" required className="w-full px-4 py-2 border rounded-lg text-sm" placeholder="e.g. Samsung" value={formData.deviceBrand} onChange={e => handleInputChange('deviceBrand', e.target.value)} />
                            </div>
                            <div>
                               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Model</label>
                               <input type="text" required className="w-full px-4 py-2 border rounded-lg text-sm" placeholder="e.g. Galaxy S21" value={formData.deviceModel} onChange={e => handleInputChange('deviceModel', e.target.value)} />
                            </div>
                            <div>
                               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">IMEI (Optional)</label>
                               <input type="text" className="w-full px-4 py-2 border rounded-lg text-sm font-mono" placeholder="IMEI Number" value={formData.imei} onChange={e => handleInputChange('imei', e.target.value)} />
                            </div>
                            <div>
                               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Passcode / Pattern</label>
                               <input type="text" className="w-full px-4 py-2 border rounded-lg text-sm" placeholder="Unlock code" value={formData.passcode} onChange={e => handleInputChange('passcode', e.target.value)} />
                            </div>
                         </div>
                      </div>

                      {/* Issue Info */}
                      <div className="space-y-4">
                         <h4 className="font-bold text-red-600 text-sm uppercase tracking-wider border-b border-red-100 pb-2 flex items-center gap-2">
                             <AlertTriangle className="w-4 h-4" /> Problem Details
                         </h4>
                         <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Error Type</label>
                            <input type="text" required className="w-full px-4 py-2 border rounded-lg text-sm" placeholder="e.g. Screen Replacement, Software" value={formData.errorType} onChange={e => handleInputChange('errorType', e.target.value)} />
                         </div>
                         <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Description</label>
                            <textarea rows={3} className="w-full px-4 py-2 border rounded-lg text-sm resize-none" placeholder="Detailed description of the issue..." value={formData.errorDescription} onChange={e => handleInputChange('errorDescription', e.target.value)} />
                         </div>
                         <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Estimated Cost</label>
                            <div className="relative">
                               <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-bold text-xs">K</span>
                               <input type="number" required className="w-full pl-8 pr-4 py-2 border rounded-lg text-sm font-bold" placeholder="0" value={formData.estimatedCost} onChange={e => handleInputChange('estimatedCost', e.target.value)} />
                            </div>
                         </div>
                      </div>

                      <div className="pt-4">
                         <button type="submit" className="w-full py-4 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 transition-all shadow-lg flex items-center justify-center gap-2">
                            <Save className="w-5 h-5" /> {editingId ? 'Update Ticket' : 'Create Repair Ticket'}
                         </button>
                      </div>
                   </form>
                </div>
             </div>
         );

      case 'active-tickets':
      case 'completed-tickets':
         const isActiveView = currentView === 'active-tickets';
         const filteredTickets = getFilteredTickets(isActiveView ? 'active' : 'completed');

         return (
             <div className="bg-white rounded-2xl shadow-sm border border-slate-100 flex flex-col h-full animate-fade-in">
                <div className="p-6 border-b border-slate-100">
                   <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                      <h3 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                         {isActiveView ? <Clock className="w-5 h-5 text-indigo-600" /> : <CheckCircle className="w-5 h-5 text-indigo-600" />} 
                         {isActiveView ? 'Active Repairs' : 'Repair History'}
                      </h3>
                      <div className="relative">
                         <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                         <input type="text" placeholder="Search ticket..." className="pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none focus:border-indigo-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
                      </div>
                   </div>
                   {isActiveView && (
                     <div className="flex gap-2 mt-4">
                        {['All', 'Pending', 'In Progress'].map(s => (
                           <button key={s} onClick={() => setStatusFilter(s as any)} className={`px-3 py-1 rounded-lg text-xs font-bold transition-all ${statusFilter === s ? 'bg-indigo-100 text-indigo-700' : 'text-slate-500 hover:bg-slate-50'}`}>{s}</button>
                        ))}
                     </div>
                   )}
                </div>

                <div className="flex-1 overflow-auto">
                   <table className="w-full text-left">
                      <thead className="bg-slate-50 sticky top-0 z-10">
                         <tr className="text-slate-500 text-xs uppercase font-bold tracking-wider">
                            <th className="p-4">ID / Date</th>
                            <th className="p-4">Customer</th>
                            <th className="p-4">Device Info</th>
                            <th className="p-4 text-right">Est. Cost</th>
                            <th className="p-4 text-center">Status</th>
                            <th className="p-4 text-right">Actions</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                         {filteredTickets.map(t => (
                            <tr key={t.id} className="hover:bg-slate-50 group">
                               <td className="p-4">
                                  <span className="font-bold text-indigo-600 text-sm block">{t.id}</span>
                                  <span className="text-xs text-slate-400">{t.date}</span>
                                  {/* Over 15 Days Alert */}
                                  {isActiveView && (new Date().getTime() - new Date(t.date).getTime()) > (15 * 24 * 60 * 60 * 1000) && (
                                     <div className="flex items-center gap-1 text-[10px] font-bold text-red-600 bg-red-50 px-2 py-1 rounded-md mt-1 border border-red-100 w-fit animate-pulse">
                                        <AlertTriangle className="w-3 h-3" /> Over 15 Days
                                     </div>
                                  )}
                               </td>
                               <td className="p-4">
                                  <span className="block font-bold text-slate-800 text-sm">{t.customerName}</span>
                                  <span className="text-xs text-slate-500">{t.phoneNumber}</span>
                               </td>
                               <td className="p-4">
                                  <span className="block font-medium text-slate-700 text-sm">{t.deviceBrand} {t.deviceModel}</span>
                                  <span className="text-xs text-slate-500">{t.errorType}</span>
                               </td>
                               <td className="p-4 text-right font-bold text-slate-700 text-sm">
                                  {t.estimatedCost.toLocaleString()}
                               </td>
                               <td className="p-4 text-center">
                                  <button onClick={() => initiateServiceAction(t)} className={`px-3 py-1 rounded-full text-xs font-bold transition-all hover:scale-105 ${
                                     t.status === 'Completed' ? 'bg-emerald-100 text-emerald-700' :
                                     t.status === 'Pending' ? 'bg-amber-100 text-amber-700' :
                                     t.status === 'In Progress' ? 'bg-blue-100 text-blue-700' : 'bg-red-100 text-red-700'
                                  }`}>
                                     {t.status}
                                  </button>
                               </td>
                               <td className="p-4 text-right">
                                  <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                     <button onClick={() => setViewingTicket(t)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg"><Eye className="w-4 h-4" /></button>
                                     <button onClick={() => handleEdit(t)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg"><Edit className="w-4 h-4" /></button>
                                     <button onClick={() => initiateDelete(t)} className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                                  </div>
                               </td>
                            </tr>
                         ))}
                         {filteredTickets.length === 0 && (
                            <tr><td colSpan={6} className="p-8 text-center text-slate-400 italic">No tickets found.</td></tr>
                         )}
                      </tbody>
                   </table>
                </div>
             </div>
         );

      case 'backup':
         return (
             <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm animate-fade-in max-w-4xl mx-auto">
                <h3 className="font-bold text-slate-800 mb-6 flex items-center gap-2">
                   <Save className="w-5 h-5 text-indigo-600" /> Repair Data Backup
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div className="p-8 border-2 border-dashed border-slate-200 rounded-xl flex flex-col items-center justify-center text-center gap-4 hover:border-indigo-300 transition-colors bg-slate-50/50">
                      <div className="p-3 bg-white rounded-full shadow-sm"><Download className="w-6 h-6 text-indigo-500" /></div>
                      <h4 className="font-bold text-slate-700">Backup Tickets</h4>
                      <button onClick={handleBackupNow} className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-medium flex items-center gap-2"><Save className="w-4 h-4" /> Download JSON</button>
                   </div>
                   <div className="p-8 border-2 border-dashed border-slate-200 rounded-xl flex flex-col items-center justify-center text-center gap-4 hover:border-emerald-300 transition-colors bg-slate-50/50">
                      <div className="p-3 bg-white rounded-full shadow-sm"><Upload className="w-6 h-6 text-emerald-500" /></div>
                      <h4 className="font-bold text-slate-700">Restore Tickets</h4>
                      <input type="file" ref={fileInputRef} onChange={handleImportData} accept="application/json" className="hidden" />
                      <button onClick={() => fileInputRef.current?.click()} className="px-6 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 font-medium flex items-center gap-2"><Upload className="w-4 h-4" /> Select File</button>
                   </div>
                </div>
             </div>
         );
    }
  };

  return (
    <div className="flex h-screen w-full bg-slate-50 overflow-hidden font-sans">
      <aside className="w-64 bg-white border-r border-slate-200 flex flex-col z-20 shadow-xl shadow-slate-200/50">
        <div className="p-6 border-b border-slate-100">
          <h2 className="font-display font-bold text-xl text-slate-900">{BRAND_NAME}</h2>
          <p className="text-xs font-bold text-orange-600 uppercase tracking-widest mt-1">Repair Service</p>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto pt-6">
          {menuItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id as View)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
                currentView === item.id
                  ? 'bg-orange-50 text-orange-600 font-bold shadow-sm'
                  : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900 font-medium'
              }`}
            >
              <item.icon className={`w-5 h-5 ${currentView === item.id ? 'text-orange-600' : 'text-slate-400'}`} />
              <span>{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-100">
          <button onClick={handleAutoBackupAndLogout} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-red-500 hover:bg-red-50 font-medium transition-colors">
            <LogOut className="w-5 h-5" />
            <span>Sign Out</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-16 bg-white/80 backdrop-blur-md border-b border-slate-200 flex items-center justify-between px-8 z-10 sticky top-0">
          <h1 className="text-xl font-bold text-slate-800 capitalize">{currentView.replace('-', ' ')}</h1>
          <div className="flex items-center gap-4">
             <div className="w-8 h-8 rounded-full bg-orange-100 border border-orange-200 flex items-center justify-center text-orange-700 font-bold text-xs">AD</div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 relative">
           <div className="fixed top-0 right-0 -z-10 opacity-30 pointer-events-none">
             <div className="absolute top-20 right-20 w-96 h-96 bg-orange-200 rounded-full mix-blend-multiply filter blur-3xl opacity-20 animate-blob"></div>
             <div className="absolute top-40 right-60 w-96 h-96 bg-amber-200 rounded-full mix-blend-multiply filter blur-3xl opacity-20 animate-blob animation-delay-2000"></div>
           </div>
           {renderContent()}
        </div>
      </main>

      {/* Service Action Modal */}
      {isServiceModalOpen && serviceActionTicket && (
         <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm animate-fade-in">
            <div className="bg-white w-full max-w-sm rounded-3xl shadow-2xl p-6 animate-slide-up">
               <h3 className="font-bold text-lg mb-4">Update Repair Status</h3>
               <p className="text-sm text-slate-500 mb-4">
                  Ticket: <span className="font-bold text-slate-800">{serviceActionTicket.id}</span>
               </p>
               <form onSubmit={handleServiceSubmit} className="space-y-4">
                  <div>
                     <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Status</label>
                     <select 
                       className="w-full px-3 py-2 border rounded-lg bg-white"
                       value={serviceActionStatus}
                       onChange={e => setServiceActionStatus(e.target.value as RepairStatus)}
                     >
                        <option value="Pending">Pending</option>
                        <option value="In Progress">In Progress</option>
                        <option value="Completed">Completed</option>
                        <option value="Cancelled">Cancelled</option>
                        <option value="Cannot Fix">Cannot Fix</option>
                     </select>
                  </div>

                  {serviceActionStatus === 'Completed' && (
                     <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Final Cost</label>
                        <input 
                           type="number" 
                           className="w-full px-3 py-2 border rounded-lg font-bold"
                           value={serviceActionCost} 
                           onChange={e => setServiceActionCost(e.target.value)}
                        />
                     </div>
                  )}

                  <div>
                     <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Technician Note</label>
                     <textarea 
                        className="w-full px-3 py-2 border rounded-lg text-sm resize-none"
                        rows={3}
                        value={serviceNote}
                        onChange={e => setServiceNote(e.target.value)}
                        placeholder="Work done, parts replaced..."
                     />
                  </div>

                  <div className="flex gap-3 pt-2">
                     <button type="button" onClick={() => setIsServiceModalOpen(false)} className="flex-1 py-2 bg-slate-100 rounded-lg text-slate-600 font-bold">Cancel</button>
                     <button type="submit" className="flex-1 py-2 bg-indigo-600 text-white rounded-lg font-bold">Update</button>
                  </div>
               </form>
            </div>
         </div>
      )}

      {/* Security Check Modal */}
      {isSecurityModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm animate-fade-in">
           <div className="bg-white w-full max-w-sm rounded-3xl shadow-2xl overflow-hidden scale-100 animate-slide-up mx-4">
             <div className="p-6 bg-slate-800 flex justify-between items-center border-b border-slate-700">
               <h3 className="text-white font-bold text-lg flex items-center gap-2">
                 <ShieldAlert className="w-5 h-5 text-indigo-400" /> Security Check
               </h3>
               <button onClick={() => setIsSecurityModalOpen(false)} className="text-white/60 hover:text-white transition-colors"><X className="w-6 h-6" /></button>
             </div>
             <form onSubmit={handleSecuritySubmit} className="p-6 space-y-4">
               <p className="text-sm text-slate-500 text-center">Deleting Ticket <span className="font-bold text-slate-800">{securityActionTicket?.id}</span></p>
               <div>
                 <input type="password" autoFocus required className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Password" value={securityPassword} onChange={e => setSecurityPassword(e.target.value)} />
               </div>
               {securityError && <div className="p-3 bg-red-50 text-red-600 text-sm rounded-xl font-bold text-center border border-red-100">{securityError}</div>}
               <div className="pt-2 flex gap-3">
                 <button type="button" onClick={() => setIsSecurityModalOpen(false)} className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-bold hover:bg-slate-200">Cancel</button>
                 <button type="submit" className="flex-1 py-3 bg-red-600 text-white rounded-xl font-bold shadow-lg hover:bg-red-700">Delete</button>
               </div>
             </form>
           </div>
        </div>
      )}

      {/* View/Print Ticket Modal */}
      {viewingTicket && (
         <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-sm animate-fade-in p-4 overflow-y-auto">
            <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden flex flex-col my-auto animate-slide-up">
               <div className="p-4 bg-slate-800 text-white flex justify-between items-center print:hidden">
                  <h3 className="font-bold">Ticket Details</h3>
                  <div className="flex gap-2">
                     <button onClick={() => handlePrintTicket(viewingTicket)} className="p-2 bg-indigo-600 rounded hover:bg-indigo-700"><Printer className="w-4 h-4" /></button>
                     <button onClick={() => setViewingTicket(null)} className="p-2 hover:bg-slate-700 rounded"><X className="w-4 h-4" /></button>
                  </div>
               </div>

               <div id="ticket-receipt" className="p-8 bg-white text-slate-800">
                  <div className="text-center border-b-2 border-slate-800 pb-4 mb-4">
                     <h1 className="text-2xl font-bold uppercase">{BRAND_NAME}</h1>
                     <p className="text-xs font-bold uppercase mt-1">Mobile Service Center</p>
                     <p className="text-xs mt-1">{BRAND_ADDRESS}</p>
                     <p className="text-xs font-bold">{BRAND_CONTACT}</p>
                  </div>

                  <div className="text-center mb-6">
                     <h2 className="text-xl font-bold border-2 border-slate-800 inline-block px-4 py-1 rounded">REPAIR TICKET</h2>
                     <p className="text-sm font-mono font-bold mt-2">{viewingTicket.id}</p>
                     <p className="text-xs text-slate-500">{viewingTicket.date}</p>
                  </div>

                  <div className="space-y-4 text-sm">
                     <div className="grid grid-cols-3 gap-2 border-b border-slate-100 pb-2">
                        <span className="font-bold text-slate-500">Customer:</span>
                        <span className="col-span-2 font-bold">{viewingTicket.customerName}</span>
                        <span className="font-bold text-slate-500">Phone:</span>
                        <span className="col-span-2">{viewingTicket.phoneNumber}</span>
                     </div>

                     <div className="grid grid-cols-3 gap-2 border-b border-slate-100 pb-2">
                        <span className="font-bold text-slate-500">Device:</span>
                        <span className="col-span-2 font-bold">{viewingTicket.deviceBrand} {viewingTicket.deviceModel}</span>
                        {viewingTicket.imei && (
                           <>
                              <span className="font-bold text-slate-500">IMEI:</span>
                              <span className="col-span-2 font-mono text-xs">{viewingTicket.imei}</span>
                           </>
                        )}
                        <span className="font-bold text-slate-500">Passcode:</span>
                        <span className="col-span-2 font-mono bg-slate-100 px-2 rounded w-fit">{viewingTicket.passcode || 'N/A'}</span>
                     </div>

                     <div className="border-b border-slate-100 pb-2">
                        <p className="font-bold text-slate-500 mb-1">Issue / Error:</p>
                        <p className="font-bold text-red-600">{viewingTicket.errorType}</p>
                        <p className="text-xs text-slate-600 mt-1">{viewingTicket.errorDescription}</p>
                     </div>

                     <div className="flex justify-between items-center text-lg pt-2">
                        <span className="font-bold">Estimated Cost:</span>
                        <span className="font-bold text-indigo-700">{viewingTicket.estimatedCost.toLocaleString()} K</span>
                     </div>
                  </div>

                  <div className="mt-8 pt-4 border-t border-slate-300 text-[10px] text-slate-500 text-center leading-relaxed">
                     <p>Items left over 30 days will be disposed of.</p>
                     <p>We are not responsible for data loss. Please backup data.</p>
                     <p className="font-bold mt-2">Thank you for choosing us!</p>
                  </div>
               </div>
            </div>
         </div>
      )}
    </div>
  );
};
